def has_2_above(grid, r, c):
    for row in range(r-1, -1, -1):
        if grid[row][c] == 2:
            return True
    return False

def has_2_below(grid, r, c):
    for row in range(r+1, len(grid)):
        if grid[row][c] == 2:
            return True
    return False

def has_2_left(grid, r, c):
    for col in range(c-1, -1, -1):
        if grid[r][col] == 2:
            return True
    return False

def has_2_right(grid, r, c):
    for col in range(c+1, len(grid[0])):
        if grid[r][col] == 2:
            return True
    return False

def transform(grid):
    if not grid or not grid[0]:
        return grid

    result = [row[:] for row in grid]  # copy
    h, w = len(grid), len(grid[0])

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                has_above = has_2_above(grid, r, c)
                has_below = has_2_below(grid, r, c)
                has_left = has_2_left(grid, r, c)
                has_right = has_2_right(grid, r, c)

                if (has_above and has_below) or (has_left and has_right):
                    result[r][c] = 1  # fill this cell

    return result

