def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Check horizontal
                l = nearest_2_left(grid, r, c)
